from collections import deque
R=C=30
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c] and (r,c) not in seen:
   q=deque([(r,c)]); seen.add((r,c)); comp=[]
   while q:
    x,y=q.popleft(); comp.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     z=(x+dx,y+dy)
     if 0<=z[0]<R and 0<=z[1]<C and grid[z[0]][z[1]] and z not in seen:
      seen.add(z);q.append(z)
   comps.append(comp)
[(len(x),[(r,c,grid[r][c]) for r,c in x if grid[r][c]>1]) for x in comps if any(grid[r][c]>1 for r,c in x)]

out=[row[:] for row in grid]
seed_colors={}
for comp in comps:
 colors={grid[r][c] for r,c in comp if grid[r][c]>1}
 if colors: seed_colors.update({p:next(iter(colors)) for p in comp})
colored=[]
for r in range(1,R-1):
 for c in range(1,C-1):
  if all(grid[i][j]!=0 for i in range(r-1,r+2) for j in range(c-1,c+2)):
   col=seed_colors.get((r,c))
   if col:
    out[r][c]=col; colored.append((r,c,col))
len(colored),colored
